// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount != 10 ether);
        uint256 initialBalance = address(this).balance;
        vm.deal(address(c), 1 ether);
        (bool ok,) = address(c).call{value: amount}("");
        if (ok) {
            assertTrue(c.pastBlockTime() < block.timestamp);
        }
        vm.deal(address(this), initialBalance);
    }
}

